/**
 * MCP server — exposes Critical as a tool an agent can call directly.
 *
 *   npx critical mcp           # (wired via the bin in a real release)
 *   node src/mcp.js
 *
 * The point: an agent like Claude Code shouldn't have to shell out and parse stdout. It calls
 * `optimize_critical_css` with a path or HTML string and gets the structured report back as the
 * tool result — engine chosen, why, bytes saved, warnings — which it can reason about and act on.
 *
 * `@modelcontextprotocol/sdk` is an OPTIONAL peer dependency, imported lazily.
 */
import { critical } from "./index.js";

const TOOL = {
  name: "optimize_critical_css",
  description:
    "Extract above-the-fold critical CSS for an HTML document and (optionally) inline it, " +
    "deferring the rest. Auto-selects a no-browser static engine for rendered/SSG/SSR HTML or a " +
    "real-browser render engine for SPA shells. Returns the critical CSS, the rewritten HTML, and " +
    "a structured report explaining the engine choice and bytes saved.",
  inputSchema: {
    type: "object",
    properties: {
      src: { type: "string", description: "Path or URL to an HTML file. Provide this OR html." },
      html: { type: "string", description: "Raw HTML source. Provide this OR src." },
      css: {
        type: "array",
        items: { type: "string" },
        description: "Optional explicit CSS file paths/globs/strings.",
      },
      engine: {
        type: "string",
        enum: ["auto", "static", "render"],
        default: "auto",
        description:
          "Engine selection. 'auto' picks static for rendered HTML, render for SPA shells.",
      },
      inline: {
        type: "boolean",
        default: true,
        description: "Inline critical CSS and defer the rest.",
      },
      width: { type: "number", default: 1300 },
      height: { type: "number", default: 900 },
    },
  },
};

export async function createServer() {
  const { Server } = await loadSdk("server/index.js");
  const { CallToolRequestSchema, ListToolsRequestSchema } = await loadSdk("types.js");

  const server = new Server(
    { name: "critical", version: "9.0.0-next.0" },
    { capabilities: { tools: {} } },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: [TOOL] }));

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    if (request.params.name !== TOOL.name) {
      throw new Error(`Unknown tool: ${request.params.name}`);
    }
    const args = request.params.arguments ?? {};
    const res = await critical({ inline: true, ...args });
    return {
      content: [
        { type: "text", text: JSON.stringify(res.report, null, 2) },
        { type: "text", text: res.html },
      ],
      // structuredContent lets a capable client consume the report without re-parsing text
      structuredContent: res.report,
    };
  });

  return server;
}

async function loadSdk(subpath) {
  try {
    return await import(`@modelcontextprotocol/sdk/${subpath}`);
  } catch {
    throw new Error(
      "The MCP server needs @modelcontextprotocol/sdk (optional peer dependency).\n" +
        "Install it:  npm i @modelcontextprotocol/sdk",
    );
  }
}

// Allow `node src/mcp.js` to start a stdio server directly.
if (import.meta.url === `file://${process.argv[1]}`) {
  const { StdioServerTransport } = await loadSdk("server/stdio.js");
  const server = await createServer();
  await server.connect(new StdioServerTransport());
}

/**
 * MCP server — exposes `critical` as a Model Context Protocol tool an agent can call directly.
 *
 * Requires the optional `@modelcontextprotocol/sdk` peer dependency.
 */
import type { Server } from "@modelcontextprotocol/sdk/server/index.js";
import type { CriticalOptions } from "./index.js";

/** Arguments accepted by the `optimize_critical_css` MCP tool. */
export interface OptimizeCriticalCssArgs {
  /** Path or URL to an HTML file. Provide this **or** `html`. */
  src?: string;
  /** Raw HTML source. Provide this **or** `src`. */
  html?: string;
  /** Optional explicit CSS file paths/globs/strings. */
  css?: string[];
  /**
   * Engine selection. `"auto"` picks static for rendered HTML, render for SPA shells.
   * @default "auto"
   */
  engine?: CriticalOptions["engine"];
  /**
   * Inline critical CSS and defer the rest.
   * @default true
   */
  inline?: boolean;
  /** Render-engine viewport width.
   * @default 1300
   */
  width?: number;
  /** Render-engine viewport height.
   * @default 900
   */
  height?: number;
}

/**
 * Start a Model Context Protocol server exposing the `optimize_critical_css` tool.
 *
 * @returns The MCP server instance. Connect it to a transport (e.g. `StdioServerTransport`) to serve.
 */
export function createServer(): Promise<Server>;

/**
 * Regression guard for the Critical-vs-Beasties benchmark in COMPARISON.md: the render engine's
 * critical payload stays meaningfully smaller on long pages (it excludes below-the-fold CSS), and
 * it covers above-the-fold CSS on un-rendered SPA shells. Skips when Beasties/Playwright absent.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { critical } from "../src/index.js";
import {
  runBeasties,
  covers,
  ABOVE_FOLD,
  BELOW_FOLD,
  FIXTURES,
  hasBeasties,
  hasPlaywright,
} from "../bench/lib.mjs";

const notReady = !((await hasBeasties()) && (await hasPlaywright()));

/** The headline number. We assert ≥20%; the prototype currently delivers ~64%. */
const MIN_REDUCTION = 0.2;

describe("critical v9 vs Beasties", { skip: notReady && "requires beasties + playwright" }, () => {
  test(`rendered page: critical payload is ≥${MIN_REDUCTION * 100}% smaller than Beasties`, async () => {
    const beasties = await runBeasties("long.html");
    const v9 = await critical({ src: path.join(FIXTURES, "long.html"), engine: "render" });
    const v9Bytes = v9.report.bytes.critical;

    const reduction = 1 - v9Bytes / beasties.bytes;
    assert.ok(
      reduction >= MIN_REDUCTION,
      `expected ≥${MIN_REDUCTION * 100}% smaller, got ${(reduction * 100).toFixed(1)}% (v9 ${v9Bytes}B vs Beasties ${beasties.bytes}B)`,
    );

    // …and the reason it's smaller: v9 doesn't leak below-the-fold CSS into the critical set.
    assert.equal(covers(v9.css, BELOW_FOLD).length, 0, "v9 leaked below-fold CSS");
    assert.ok(
      covers(beasties.css, BELOW_FOLD).length > 0,
      "fixture invalid: Beasties should inline below-fold CSS",
    );

    // Same visible result: every above-the-fold selector is still present.
    assert.equal(
      covers(v9.css, ABOVE_FOLD).length,
      ABOVE_FOLD.length,
      "v9 dropped an above-fold selector",
    );
  });

  test("SPA shell: v9 covers above-the-fold UI that Beasties misses entirely", async () => {
    const beasties = await runBeasties("spa-app.html");
    const v9 = await critical({ src: path.join(FIXTURES, "spa-app.html"), engine: "auto" });

    const beastiesCoverage = covers(beasties.css, ABOVE_FOLD).length;
    const v9Coverage = covers(v9.css, ABOVE_FOLD).length;

    assert.equal(beastiesCoverage, 0, "Beasties unexpectedly saw the rendered app");
    assert.equal(v9Coverage, ABOVE_FOLD.length, "v9 should cover the full above-the-fold set");
    assert.ok(v9Coverage > beastiesCoverage);
  });
});

/**
 * Issue regressions that live in the browser-free static path (deterministic, no Playwright).
 *
 *   #580 — modern CSS (@layer, @container, :where, :has) must pass through intact; Lightning CSS
 *          minifies without down-leveling, and the css-tree pruning recurses into grouping
 *          at-rules instead of dropping them.
 *   #613 — a custom property whose name starts with a digit (`--1x`) must survive parse + emit.
 *
 * Render-path regressions (#615 lazy iframes, #611 JS-injected stylesheets) are covered by the
 * spa/remote suites, which require a browser and skip when one isn't installed.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { critical } from "../src/index.js";

describe("issue regressions (static path)", () => {
  test("#580 — preserves @layer, @container, :where and :has", async () => {
    const html =
      "<!doctype html><html><head><style>" +
      "@layer base { .card { color: red } }" +
      "@container (min-width: 0px) { .card { color: blue } }" +
      ".card:where(.card) { outline: 1px solid }" +
      ".list:has(.item) { padding: 0 }" +
      "</style></head><body>" +
      '<section class="list"><article class="card"><h1>Modern CSS heading here</h1>' +
      '<span class="item">i</span></article></section>' +
      "</body></html>";

    const { css, report } = await critical({ html });
    assert.equal(report.engine, "static");
    assert.match(css, /@layer/);
    assert.match(css, /@container/);
    assert.match(css, /:where/);
    assert.match(css, /:has/);
  });

  test("#613 — writes output when a custom property name starts with a digit", async () => {
    const html =
      "<!doctype html><html><head><style>" +
      ":root{--1x:4px}" +
      ".card{width:var(--1x)}" +
      "</style></head><body>" +
      '<header class="card"><h1>Numeric custom property</h1></header>' +
      "<main><p>Real body content here.</p></main></body></html>";

    const { css, report } = await critical({ html });
    assert.equal(report.engine, "static");
    assert.match(css, /--1x:4px/);
    assert.match(css, /var\(--1x\)/);
  });
});

/**
 * SPA tests — an empty shell that only becomes a page after JS runs, which a browser-free pass
 * has no markup to match against. These exercise the real render engine end-to-end (Playwright),
 * so they auto-skip when a browser isn't installed.
 */
import { test, describe, before } from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { critical } from "../src/index.js";
import { FIXTURES, ABOVE_FOLD, BELOW_FOLD, covers, hasPlaywright } from "../bench/lib.mjs";

const SPA = path.join(FIXTURES, "spa-app.html");
// Skips cleanly when no browser is installed; CI provisions Chrome so these run there.
const noBrowser = !(await hasPlaywright());

describe("SPA render engine", { skip: noBrowser && "requires Playwright" }, () => {
  let res;
  before(async () => {
    res = await critical({ src: SPA, engine: "auto" });
  });

  test("auto-routes the empty shell to the render engine", () => {
    assert.equal(res.report.engine, "render");
    assert.match(res.report.reason, /shell/i);
  });

  test("covers ALL above-the-fold selectors the app renders at runtime", () => {
    const got = covers(res.css, ABOVE_FOLD);
    assert.equal(
      got.length,
      ABOVE_FOLD.length,
      `missing: ${ABOVE_FOLD.filter((s) => !got.includes(s))}`,
    );
  });

  test("excludes below-the-fold selectors (viewport-aware, unlike used-CSS tools)", () => {
    assert.equal(covers(res.css, BELOW_FOLD).length, 0);
  });

  test("always keeps :root custom properties and the reset", () => {
    assert.match(res.css, /--brand/);
    assert.match(res.css, /box-sizing:border-box/);
  });

  test("inline mode injects critical <style> + defers the real sheet without inline JS", async () => {
    const { html, report } = await critical({ src: SPA, inline: true });
    assert.match(html, /<style data-critical/);
    assert.match(html, /rel="preload"/);
    assert.doesNotMatch(html, /onload=/);
    assert.deepEqual(report.stylesheetsDeferred, ["/app.css"]);
  });

  test("multiple viewports union their above-the-fold sets", async () => {
    const { css } = await critical({
      src: SPA,
      engine: "render",
      dimensions: [
        { width: 390, height: 844 }, // mobile
        { width: 1300, height: 900 }, // desktop
      ],
    });
    assert.equal(covers(css, ABOVE_FOLD).length, ABOVE_FOLD.length);
  });

  test("render output is deterministic across runs", async () => {
    const again = await critical({ src: SPA, engine: "render" });
    const baseline = await critical({ src: SPA, engine: "render" });
    assert.equal(again.css, baseline.css);
  });
});

/**
 * Remote-source tests (render engine over HTTP). Regression guards for two bugs caught in review:
 *   1. The render engine must navigate to the document URL so the browser fetches and runs
 *      external/module scripts and relative assets - setContent with no base cannot.
 *   2. The source loader must resolve a relative stylesheet against the *remote* document URL and
 *      fetch it, not look for it on the local filesystem.
 *
 * Serves the fixtures over a throwaway HTTP server so both paths are exercised end to end.
 * Auto-skips when Playwright isn't installed.
 */
import { test, describe, before, after } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { critical } from "../src/index.js";
import { FIXTURES, ABOVE_FOLD, covers, hasPlaywright } from "../bench/lib.mjs";

const noBrowser = !(await hasPlaywright());
const TYPES = { ".html": "text/html", ".css": "text/css", ".js": "text/javascript" };

describe("remote src over HTTP", { skip: noBrowser && "requires Playwright" }, () => {
  let server;
  let res;

  before(async () => {
    server = http.createServer(async (req, response) => {
      try {
        const rel = decodeURI(req.url.split("?")[0]).replace(/^\//, "");
        const file = path.join(FIXTURES, rel);
        const body = await readFile(file);
        response.setHeader("content-type", TYPES[path.extname(file)] ?? "application/octet-stream");
        response.end(body);
      } catch {
        response.statusCode = 404;
        response.end("not found");
      }
    });
    await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
    const base = `http://127.0.0.1:${server.address().port}`;
    res = await critical({ src: `${base}/spa-external.html`, engine: "render" });
  });

  after(() => server?.close());

  test("renders an SPA whose UI comes from an external module script", () => {
    // If the browser never loaded /spa-external.js, #root stays empty and coverage is 0.
    assert.equal(res.report.engine, "render");
    assert.equal(
      covers(res.css, ABOVE_FOLD).length,
      ABOVE_FOLD.length,
      "external module script did not render into the shell",
    );
  });

  test("resolves a relative stylesheet against the remote document URL", () => {
    // bundle CSS comes only from the source loader. If the relative <link href="app.css"> were
    // looked up on local disk instead of fetched from the server, this would be 0 bytes.
    assert.ok(
      res.report.bytes.stylesheets > 0,
      "relative stylesheet was not fetched from the server",
    );
    assert.match(res.css, /\.hero/);
  });
});

/**
 * `css` option tests. The source loader merges extra CSS — raw strings, file paths, and globs,
 * or an array of those — on top of what the document links. Everything routes to the static
 * engine, so the extra rules only survive if their selectors match the delivered DOM; that
 * doubles as proof the CSS was actually ingested.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { critical } from "../src/index.js";

// Real markup (4 meaningful elements, >10 chars of text) so routing stays on the static engine.
const HTML =
  "<!doctype html><html><head></head><body>" +
  '<header class="hero"><h1>Above the fold title</h1></header>' +
  '<main><p class="lead">Body copy for the page.</p></main>' +
  "</body></html>";

async function tmp() {
  return mkdtemp(path.join(os.tmpdir(), "critical-css-"));
}

describe("css option", () => {
  test("accepts a raw CSS string alongside the document", async () => {
    const { css } = await critical({
      html: HTML,
      css: ".hero{color:red}.ghost{color:blue}",
    });
    assert.match(css, /\.hero/); // matches <header>, kept
    assert.doesNotMatch(css, /\.ghost/); // no matching element, dropped
  });

  test("reads a CSS file path (resolved against base)", async () => {
    const dir = await tmp();
    try {
      await writeFile(path.join(dir, "extra.css"), ".lead{font-weight:bold}");
      const { css } = await critical({ html: HTML, base: dir, css: "extra.css" });
      assert.match(css, /\.lead/);
      assert.match(css, /font-weight:(bold|700)/); // lightningcss normalizes bold -> 700
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });

  test("expands a glob into multiple stylesheets", async () => {
    const dir = await tmp();
    try {
      await writeFile(path.join(dir, "a.css"), ".hero{margin:0}");
      await writeFile(path.join(dir, "b.css"), ".lead{padding:0}");
      const { css } = await critical({ html: HTML, base: dir, css: "*.css" });
      assert.match(css, /\.hero/);
      assert.match(css, /\.lead/);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });

  test("accepts an array mixing raw strings and file paths", async () => {
    const dir = await tmp();
    try {
      await writeFile(path.join(dir, "extra.css"), ".lead{color:green}");
      const { css } = await critical({
        html: HTML,
