/**
 * foldAware + warning-path tests for the static engine.
 *
 * A `[data-critical-fold]` container scopes matching to the above-the-fold subtree, so rules
 * used only below it are dropped. Turning that off (foldAware:false / --no-fold) falls back to
 * whole-document "used CSS" and surfaces a warning. A document with no CSS short-circuits to
 * engine "none". All static — no browser.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { critical } from "../src/index.js";

// A fold container wrapping the hero; the footer sits below the fold.
const FOLD_HTML =
  "<!doctype html><html><head><style>.in{color:red}.out{color:blue}</style></head><body>" +
  '<div data-critical-fold><header class="in"><h1>Visible hero content</h1></header></div>' +
  '<footer class="out"><p>Below-the-fold footer text.</p></footer>' +
  "</body></html>";

// Same markup, no fold hint — a plain rendered page.
const PLAIN_HTML =
  "<!doctype html><html><head><style>.a{color:red}</style></head><body>" +
  '<header class="a"><h1>Above the fold heading</h1></header>' +
  "<main><p>Rendered body content here.</p></main></body></html>";

describe("foldAware", () => {
  test("scopes matching to the fold container and drops below-fold rules", async () => {
    const { css, report } = await critical({ html: FOLD_HTML });
    assert.equal(report.engine, "static");
    assert.match(css, /\.in/); // inside the fold, kept
    assert.doesNotMatch(css, /\.out/); // below the fold, dropped
    assert.ok(report.rules.kept < report.rules.total);
    // fold-scoped output is not the "used CSS superset" — no such warning
    assert.ok(!report.warnings.some((w) => /superset of above-the-fold/.test(w)));
  });

  test("foldAware:false ignores the fold hint and keeps all used CSS", async () => {
    const { css, report } = await critical({ html: FOLD_HTML, foldAware: false });
    assert.match(css, /\.in/);
    assert.match(css, /\.out/); // fold ignored -> below-fold rule kept
    assert.ok(
      report.warnings.some((w) => /superset of above-the-fold/.test(w)),
      "expected the used-CSS superset warning",
    );
  });

  test("a page with no fold hint warns that output is a used-CSS superset", async () => {
    const { report } = await critical({ html: PLAIN_HTML });
    assert.equal(report.engine, "static");
    assert.ok(report.warnings.some((w) => /superset of above-the-fold/.test(w)));
  });
});

describe("no-CSS short-circuit", () => {
  test('a document with no stylesheets resolves to engine "none"', async () => {
    const { css, html, report } = await critical({
      html:
        "<!doctype html><html><body><header><h1>Content with no styles</h1></header>" +
        "<main><p>Nothing to extract here.</p></main></body></html>",
    });
    assert.equal(report.engine, "none");
    assert.equal(css, "");
    assert.match(html, /<h1>Content with no styles<\/h1>/); // html passes through untouched
    assert.ok(report.warnings.some((w) => /No CSS found/.test(w)));
    assert.equal(report.rules.total, 0);
  });
});

/**
 * Source-loader regressions for behaviors v8 supported that were missing in the v9 rewrite:
 *
 *   - query/hash on a stylesheet href (`styles.css?v=2`) must resolve to the file on disk
 *   - data: URI stylesheets (base64 and percent-encoded) must be decoded inline
 *   - a document <base href> must re-point relative stylesheet resolution (issue #566)
 *
 * All static — no browser.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { Buffer } from "node:buffer";
import { critical } from "../src/index.js";

const BODY =
  '<body><header class="hero"><h1>Above the fold heading</h1></header>' +
  "<main><p>Rendered body content here.</p></main></body>";

async function tmp() {
  return mkdtemp(path.join(os.tmpdir(), "critical-src-"));
}

describe("stylesheet href resolution", () => {
  test("resolves a href carrying a ?query string to the file on disk", async () => {
    const dir = await tmp();
    try {
      await writeFile(path.join(dir, "styles.css"), ".hero{color:red}");
      const { css, report } = await critical({
        html: `<!doctype html><html><head><link rel="stylesheet" href="/styles.css?v=2"></head>${BODY}</html>`,
        base: dir,
      });
      assert.ok(report.bytes.stylesheets > 0, "query-string href should still load the file");
      assert.match(css, /\.hero/);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });

  test("resolves a href with a #fragment", async () => {
    const dir = await tmp();
    try {
      await writeFile(path.join(dir, "styles.css"), ".hero{color:red}");
      const { css } = await critical({
        html: `<!doctype html><html><head><link rel="stylesheet" href="styles.css#x"></head>${BODY}</html>`,
        base: dir,
      });
      assert.match(css, /\.hero/);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });
});

describe("data: URI stylesheets", () => {
  test("decodes a base64 data URI", async () => {
    const uri = "data:text/css;base64," + Buffer.from(".hero{color:green}").toString("base64");
    const { css, report } = await critical({
      html: `<!doctype html><html><head><link rel="stylesheet" href="${uri}"></head>${BODY}</html>`,
    });
    assert.ok(report.bytes.stylesheets > 0);
    assert.match(css, /\.hero/);
  });

  test("decodes a percent-encoded data URI", async () => {
    const uri = "data:text/css," + encodeURIComponent(".hero{color:orange}");
    const { css } = await critical({
      html: `<!doctype html><html><head><link rel="stylesheet" href="${uri}"></head>${BODY}</html>`,
    });
    assert.match(css, /\.hero/);
  });
});

describe("document <base href> (#566)", () => {
  test("a path-style base href prefixes relative stylesheet hrefs", async () => {
    const dir = await tmp();
    try {
      await mkdir(path.join(dir, "assets"));
      await writeFile(path.join(dir, "assets", "app.css"), ".hero{color:teal}");
      const { css, report } = await critical({
        html: `<!doctype html><html><head><base href="/assets/"><link rel="stylesheet" href="app.css"></head>${BODY}</html>`,
        base: dir,
      });
      assert.ok(report.bytes.stylesheets > 0, "base href should redirect resolution into assets/");
      assert.match(css, /\.hero/);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });

  test("an absolute base href resolves relative sheets against it", async () => {
    const dir = await tmp();
    try {
      // Only a local file matching the *unprefixed* href exists. If the absolute base href were
      // honored, resolution would point at a remote URL and this local file would NOT be read —
      // so the sheet must come back empty, proving the base host took precedence.
      await writeFile(path.join(dir, "app.css"), ".hero{color:red}");
      const { report } = await critical({
        html: `<!doctype html><html><head><base href="https://cdn.example.test/"><link rel="stylesheet" href="app.css"></head>${BODY}</html>`,
        base: dir,
      });
      // The remote fetch fails (no such host in test), so bytes are 0 — but crucially the local
      // app.css was NOT picked up, confirming the absolute base href redirected resolution.
      assert.equal(report.bytes.stylesheets, 0);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });
});

:root { --brand: #0a7; }
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; color: #111; }

/* used above the fold */
.hero { padding: 4rem 2rem; background: var(--brand); color: #fff; }
.hero h1 { font-size: 3rem; margin: 0; }
.nav { display: flex; gap: 1rem; padding: 1rem; }
.nav a { color: var(--brand); text-decoration: none; }
.nav a:hover { text-decoration: underline; }

/* used, animated */
.spinner { width: 2rem; height: 2rem; animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse { 50% { opacity: .5; } } /* never referenced -> should be dropped */

/* not present in the document at all -> should be dropped */
.footer { padding: 8rem; background: #222; }
.modal { position: fixed; inset: 0; }
.pricing-table td { border: 1px solid #ccc; }
.blog-post pre { background: #f5f5f5; }

@media (min-width: 1000px) {
  .hero h1 { font-size: 4rem; }     /* used */
  .sidebar { width: 320px; }        /* unused -> media block trimmed */
}
